DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT105-S4-Q12$pilot$ AND c.letter=$pilot$C$pilot$ AND c.choice_text=$pilot$The degree to which technologies elicit complaints from people is always an accurate measure of the extent to which people have become dependent on them.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT105-S4-Q12 C'; END IF; END $guard$;
