INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $pilot$Statements$pilot$, $pilot$- Nearly everyone has complained about some technology problem (a billing error, lost computer files).
